use serde_json::json;
use std::{collections::BTreeSet,fs};
fn main(){let args=std::env::args().collect::<Vec<_>>();assert_eq!(args.len(),4);let data=fs::read_to_string(&args[1]).unwrap();let mut out=Vec::new();let mut name=String::new();let mut ins:Vec<(u64,String)>=Vec::new();
fn finish(out:&mut Vec<serde_json::Value>,name:&str,ins:&[(u64,String)],end:u64){if ins.is_empty(){return;}let start=ins[0].0;let mut leaders=BTreeSet::from([start,end]);for(i,(_,text))in ins.iter().enumerate(){let p=text.split_whitespace().collect::<Vec<_>>();if p[0].starts_with('j')||p[0].starts_with("call")||p[0].starts_with("ret"){if i+1<ins.len(){leaders.insert(ins[i+1].0);}if let Some(target)=p.get(1).and_then(|p|u64::from_str_radix(p,16).ok()){if (start..end).contains(&target){leaders.insert(target);}}}}let l=leaders.into_iter().collect::<Vec<_>>();let mut blocks=Vec::new();for w in l.windows(2){let ops=ins.iter().filter(|i|(w[0]..w[1]).contains(&i.0)).collect::<Vec<_>>();if !ops.is_empty(){blocks.push(json!({"start":w[0],"offset":w[0]-start,"bytes":w[1]-w[0],"instructions":ops.len(),"ifma":ops.iter().filter(|i|i.1.starts_with("vpmadd52")).count()}));}}blocks.sort_by_key(|b|std::cmp::Reverse(b["instructions"].as_u64().unwrap()));out.push(json!({"symbol":name,"start":start,"bytes_to_next_symbol":end-start,"instructions":ins.len(),"ifma":ins.iter().filter(|i|i.1.starts_with("vpmadd52")).count(),"calls":ins.iter().filter(|i|i.1.starts_with("call")).count(),"stack_subtractions":ins.iter().filter(|i|i.1.starts_with("sub    rsp,")).map(|i|i.1.clone()).collect::<Vec<_>>(),"largest_blocks":blocks.into_iter().take(10).collect::<Vec<_>>()}));}
for line in data.lines(){let l=line.trim();if l.ends_with(">:"){if let Some((a,n))=l.split_once(" <"){let address=u64::from_str_radix(a,16).unwrap();finish(&mut out,&name,&ins,address);ins.clear();name=if n.contains(&args[2]){n.trim_end_matches(":").trim_end_matches('>').to_owned()}else{String::new()};}continue;}if name.is_empty(){continue;}if let Some((a,b))=l.split_once(':'){if let Ok(addr)=u64::from_str_radix(a,16){if !b.trim().is_empty(){ins.push((addr,b.trim().into()));}}}}
assert!(ins.is_empty(),"selected function at EOF needs symbol size");assert!(!out.is_empty());let result=json!({"scope":"static conservative instruction/basic-block inventory; sizes include trailing alignment through next symbol; no dynamic cache or timing claim","functions":out});fs::write(&args[3],serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("{}",serde_json::to_string_pretty(&result).unwrap());}
